Write a Python script file named extract_dart_definitions.py with this content:

import os, re, json
from pathlib import Path

lib_path = Path('lib')
dart_files = list(lib_path.rglob('*.dart'))
print('Found', len(dart_files), 'Dart files')

class_pattern = re.compile(r'^\s*(?:abstract\s+)?(?:class|mixin|enum|typedef|extension)\s+([A-Z][a-zA-Z0-9_]*)')
function_pattern = re.compile(r'^\s*(?:[a-zA-Z0-9_<>\[\]]+\s+)?([a-z][a-zA-Z0-9_]*)\s*\([^)]*\)\s*(?:async\s*)?(?:\s*=>|\s*\{)')
variable_pattern = re.compile(r'^\s*(?:final|const|var|late\s+)?(?:[A-Z][a-zA-Z0-9_<>\[\]]*\s+)?([a-z][a-zA-Z0-9_]*)\s*=')
toplevel_var_pattern = re.compile(r'^\s*(?:final|const|var|late\s+)?([A-Z][a-zA-Z0-9_<>\[\]]*)\s+([a-z][a-zA-Z0-9_]*)\s*=')

all_definitions = {}

for dart_file in dart_files:
    try:
        content = dart_file.read_text(encoding='utf-8')
        rel_path = str(dart_file.relative_to(lib_path))
        definitions = []

        for line_num, line in enumerate(content.split('\n'), 1):
            stripped = line.strip()
            if stripped.startswith('//') or stripped.startswith('/*'):
                continue

            for match in class_pattern.finditer(line):
                name = match.group(1)
                if not name.startswith('_'):
                    definitions.append({'type': 'class', 'name': name, 'line': line_num})

            for match in function_pattern.finditer(line):
                name = match.group(1)
                if not name.startswith('_') and name not in ['if', 'for', 'while', 'switch', 'catch', 'return', 'throw', 'try', 'finally']:
                    definitions.append({'type': 'function', 'name': name, 'line': line_num})

            for match in toplevel_var_pattern.finditer(line):
                name = match.group(2)
                if not name.startswith('_'):
                    definitions.append({'type': 'variable', 'name': name, 'line': line_num})

            for match in variable_pattern.finditer(line):
                name = match.group(1)
                if not name.startswith('_') and name not in ['if', 'for', 'while', 'switch', 'catch', 'return', 'throw', 'try', 'finally']:
                    definitions.append({'type': 'variable', 'name': name, 'line': line_num})

        if definitions:
            all_definitions[rel_path] = definitions

    except Exception as e:
        print('Error reading', dart_file, ':', e)

output_path = Path('DiaoYan/_all_definitions.json')
output_path.parent.mkdir(parents=True, exist_ok=True)
output_path.write_text(json.dumps(all_definitions, indent=2, ensure_ascii=False))
print('Written to', output_path)
print('Total files with definitions:', len(all_definitions))
total_defs = sum(len(v) for v in all_definitions.values())
print('Total definitions:', total_defs)

Then run it with: python3 extract_dart_definitions.py

